package com.bank.analytics.oltp;

import com.bank.analytics.model.TxnRecord;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// OLTP: fast point operations on single accounts; keeps a transaction log.
public class OltpStore {
    private static final Logger log = Logger.getLogger(OltpStore.class.getName());
    private final Map<String, BigDecimal> balances = new HashMap<>();
    private final List<TxnRecord> txnLog = new ArrayList<>();
    private int counter = 0;

    public void openAccount(String id, BigDecimal opening) { balances.put(id, opening); }

    // Fast, single-row write — the bread and butter of OLTP.
    public void debit(String accountId, BigDecimal amount) {
        BigDecimal bal = balances.get(accountId);
        balances.put(accountId, bal.subtract(amount));
        TxnRecord r = new TxnRecord("T" + (++counter), accountId, amount);
        txnLog.add(r);
        log.info(() -> "OLTP debit " + amount + " from " + accountId
                + " (fast point write, new balance=" + balances.get(accountId) + ")");
    }

    public List<TxnRecord> drainNewTxns() { return new ArrayList<>(txnLog); }
}
