package com.bank.analytics.olap;

import com.bank.analytics.model.TxnRecord;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// OLAP: holds history; runs heavy aggregations WITHOUT touching production.
public class OlapStore {
    private static final Logger log = Logger.getLogger(OlapStore.class.getName());
    private final List<TxnRecord> fact = new ArrayList<>();

    public void bulkLoad(List<TxnRecord> records) {
        fact.addAll(records);
        log.info("OLAP bulk-loaded " + records.size() + " records into fact table");
    }

    // Heavy scan-and-aggregate — runs on the analytics system, not production.
    public Map<String, BigDecimal> totalByAccount() {
        log.info("OLAP heavy aggregation over " + fact.size() + " fact rows");
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (TxnRecord r : fact) totals.merge(r.getAccountId(), r.getAmount(), BigDecimal::add);
        return totals;
    }
}
