package com.bank.analytics.sync;

import com.bank.analytics.oltp.OltpStore;
import com.bank.analytics.olap.OlapStore;
import java.util.logging.Logger;

// Moves committed data from OLTP to OLAP (ETL / CDC), isolating the workloads.
public class SyncJob {
    private static final Logger log = Logger.getLogger(SyncJob.class.getName());

    public void sync(OltpStore oltp, OlapStore olap) {
        log.info("SYNC: copying OLTP transactions into OLAP");
        olap.bulkLoad(oltp.drainNewTxns());
    }
}
