package com.bank.analytics;

import com.bank.analytics.olap.OlapStore;
import com.bank.analytics.oltp.OltpStore;
import com.bank.analytics.sync.SyncJob;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class OltpOlapDemo {
    private static final Logger log = Logger.getLogger(OltpOlapDemo.class.getName());

    public static void main(String[] args) {
        OltpStore oltp = new OltpStore();
        oltp.openAccount("SAV2001", new BigDecimal("1000000.00"));
        oltp.openAccount("CUR3001", new BigDecimal("250000.00"));

        log.info("=== OLTP: fast point transactions (production) ===");
        oltp.debit("SAV2001", new BigDecimal("1200.00"));
        oltp.debit("CUR3001", new BigDecimal("5000.00"));
        oltp.debit("SAV2001", new BigDecimal("800.00"));

        log.info("=== SYNC OLTP → OLAP ===");
        OlapStore olap = new OlapStore();
        new SyncJob().sync(oltp, olap);

        log.info("=== OLAP: heavy analytics (separate system) ===");
        olap.totalByAccount().forEach((acc, total) ->
            log.info("ANALYTICS total spent by " + acc + " = " + total));
    }
}
